// 1. The Common Interface
interface Notification {
  send(msg: string): void;
}

// 2. The Concrete Implementations
class EmailNotification implements Notification {
  send(msg: string) { console.log(`Sending Email: ${msg}`); }
}

class PushNotification implements Notification {
  send(msg: string) { console.log(`Sending Push: ${msg}`); }
}

// 3. The Factory
class NotificationFactory {
  // The return type is the broad Interface, hiding the specific classes
  public static create(type: "email" | "push"): Notification {
    if (type === "email") return new EmailNotification();
    if (type === "push") return new PushNotification();
    throw new Error("Unknown notification type");
  }
}

// Consumer code has no idea 'EmailNotification' class exists. 
// It just uses the factory.
const notifier = NotificationFactory.create("email");
notifier.send("Welcome to the app!");
